```ts
export type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly pending: Array<() => void> = [];
  private idleWaiters: Array<() => void> = [];
  private active = 0;

  constructor(
    private readonly concurrency: number,
    private readonly maxRetries = 3,
  ) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
  }

  /** Resolves with the job's result, or rejects with its last error once retries run out. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => void this.execute(job, resolve, reject));
      this.next();
    });
  }

  /** Resolves when no job is running or waiting. */
  onIdle(): Promise<void> {
    if (this.isIdle()) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private isIdle(): boolean {
    return this.active === 0 && this.pending.length === 0;
  }

  private next(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      this.active++;
      this.pending.shift()!();
    }
    if (this.isIdle()) {
      for (const resolve of this.idleWaiters.splice(0)) resolve();
    }
  }

  private async execute<T>(
    job: Job<T>,
    resolve: (value: T) => void,
    reject: (reason: unknown) => void,
  ): Promise<void> {
    try {
      resolve(await this.runWithRetries(job));
    } catch (err) {
      reject(err);
    } finally {
      this.active--;
      this.next();
    }
  }

  private async runWithRetries<T>(job: Job<T>): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      try {
        return await job();
      } catch (err) {
        if (attempt >= this.maxRetries) throw err;
      }
    }
  }
}
