package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flagDef struct {
	name, short, usage string
	kind               string // "" for boolean flags, else the value type shown in help
	def                string
	set                func(string) error
}

type posDef struct {
	name, usage string
	target      *string
}

type Parser struct {
	name      string
	flags     []*flagDef
	byKey     map[string]*flagDef
	pos       []posDef
	restName  string
	restUsage string
	rest      []string
}

func NewParser(name string) *Parser {
	return &Parser{name: name, byKey: map[string]*flagDef{}}
}

func (p *Parser) add(f *flagDef) {
	keys := []string{"--" + f.name}
	if f.short != "" {
		keys = append(keys, "-"+f.short)
	}
	for _, k := range keys {
		if _, dup := p.byKey[k]; dup {
			panic("flag defined twice: " + k)
		}
		p.byKey[k] = f
	}
	p.flags = append(p.flags, f)
}

// Bool defines a boolean flag. short may be empty.
func (p *Parser) Bool(name, short, usage string) *bool {
	v := new(bool)
	p.add(&flagDef{name: name, short: short, usage: usage, set: func(s string) error {
		b, err := strconv.ParseBool(s)
		if err != nil {
			return fmt.Errorf("invalid boolean %q", s)
		}
		*v = b
		return nil
	}})
	return v
}

// String defines a flag that takes a string value.
func (p *Parser) String(name, short, def, usage string) *string {
	v := new(string)
	*v = def
	p.add(&flagDef{name: name, short: short, usage: usage, kind: "string", def: def,
		set: func(s string) error {
			*v = s
			return nil
		}})
	return v
}

// Int defines a flag that takes an integer value.
func (p *Parser) Int(name, short string, def int, usage string) *int {
	v := new(int)
	*v = def
	p.add(&flagDef{name: name, short: short, usage: usage, kind: "int", def: strconv.Itoa(def),
		set: func(s string) error {
			n, err := strconv.Atoi(s)
			if err != nil {
				return fmt.Errorf("invalid integer %q", s)
			}
			*v = n
			return nil
		}})
	return v
}

// Positional defines a required positional argument.
func (p *Parser) Positional(name, usage string) *string {
	v := new(string)
	p.pos = append(p.pos, posDef{name: name, usage: usage, target: v})
	return v
}

// Rest allows extra positional arguments after the defined ones; read them with Args.
func (p *Parser) Rest(name, usage string) {
	p.restName, p.restUsage = name, usage
}

// Args returns the positional arguments left after the defined ones.
func (p *Parser) Args() []string { return p.rest }

func (p *Parser) Parse(args []string) error {
	var positional []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if len(a) < 2 || a[0] != '-' {
			positional = append(positional, a)
			continue
		}
		if a == "-h" || a == "--help" {
			return ErrHelp
		}
		key, val, hasVal := strings.Cut(a, "=")
		f, ok := p.byKey[key]
		if !ok {
			return fmt.Errorf("unknown flag %s", key)
		}
		if !hasVal {
			if f.kind == "" {
				val = "true"
			} else {
				if i+1 >= len(args) {
					return fmt.Errorf("flag %s needs a value", key)
				}
				i++
				val = args[i]
			}
		}
		if err := f.set(val); err != nil {
			return fmt.Errorf("flag %s: %w", key, err)
		}
	}

	if len(positional) < len(p.pos) {
		return fmt.Errorf("missing argument <%s>", p.pos[len(positional)].name)
	}
	for i, d := range p.pos {
		*d.target = positional[i]
	}
	p.rest = positional[len(p.pos):]
	if len(p.rest) > 0 && p.restName == "" {
		return fmt.Errorf("unexpected argument %q", p.rest[0])
	}
	return nil
}

// Usage writes a help message built from the definitions.
func (p *Parser) Usage(w io.Writer) {
	line := "Usage: " + p.name + " [flags]"
	for _, d := range p.pos {
		line += " <" + d.name + ">"
	}
	if p.restName != "" {
		line += " [" + p.restName + "...]"
	}
	fmt.Fprintln(w, line)

	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	if len(p.pos) > 0 || p.restName != "" {
		fmt.Fprintln(tw, "\nArguments:")
		for _, d := range p.pos {
			fmt.Fprintf(tw, "  %s\t%s\n", d.name, d.usage)
		}
		if p.restName != "" {
			fmt.Fprintf(tw, "  %s...\t%s\n", p.restName, p.restUsage)
		}
	}
	fmt.Fprintln(tw, "\nFlags:")
	for _, f := range p.flags {
		label := "    --" + f.name
		if f.short != "" {
			label = "-" + f.short + ", --" + f.name
		}
		if f.kind != "" {
			label += " <" + f.kind + ">"
		}
		usage := f.usage
		if f.def != "" {
			usage += " (default " + f.def + ")"
		}
		fmt.Fprintf(tw, "  %s\t%s\n", label, usage)
	}
	fmt.Fprintf(tw, "  -h, --help\tshow this help\n")
	tw.Flush()
}

func main() {
	p := NewParser("copy")
	verbose := p.Bool("verbose", "v", "print each file")
	output := p.String("output", "o", "", "write report to this file")
	jobs := p.Int("jobs", "j", 4, "parallel workers")
	src := p.Positional("src", "source directory")
	dst := p.Positional("dst", "destination directory")
	p.Rest("patterns", "only copy files matching these globs")

	if err := p.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, ErrHelp) {
			p.Usage(os.Stdout)
			return
		}
		fmt.Fprintln(os.Stderr, "error:", err)
		p.Usage(os.Stderr)
		os.Exit(2)
	}
	fmt.Println(*verbose, *output, *jobs, *src, *dst, p.Args())
}
