const express = require("express");
const { Pool } = require("pg");

const pool = new Pool(); // reads PGHOST, PGUSER, PGDATABASE, ...
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function encodeCursor(row) {
  return Buffer.from(JSON.stringify([row.cursor_created_at, row.id])).toString("base64url");
}

function decodeCursor(cursor) {
  if (typeof cursor !== "string") return null;
  try {
    const [createdAt, id] = JSON.parse(Buffer.from(cursor, "base64url").toString("utf8"));
    if (typeof createdAt !== "string" || !/^\d+$/.test(String(id))) return null;
    return { createdAt, id: String(id) };
  } catch {
    return null;
  }
}

router.get("/orders", async (req, res, next) => {
  const limit = req.query.limit === undefined ? DEFAULT_LIMIT : Number(req.query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    return res.status(400).json({ error: `limit must be an integer from 1 to ${MAX_LIMIT}` });
  }

  let after = null;
  if (req.query.cursor !== undefined) {
    after = decodeCursor(req.query.cursor);
    if (!after) return res.status(400).json({ error: "invalid cursor" });
  }

  // Fetch one extra row to learn whether another page exists.
  const params = [limit + 1];
  let where = "";
  if (after) {
    where = "WHERE (created_at, id) < ($2::timestamptz, $3::bigint)";
    params.push(after.createdAt, after.id);
  }

  // created_at::text keeps microseconds; a JS Date would truncate them and break the cursor.
  const sql = `
    SELECT id, customer_id, status, total, created_at,
           created_at::text AS cursor_created_at
    FROM orders
    ${where}
    ORDER BY created_at DESC, id DESC
    LIMIT $1`;

  try {
    const { rows } = await pool.query(sql, params);
    const hasMore = rows.length > limit;
    const page = hasMore ? rows.slice(0, limit) : rows;
    res.json({
      data: page.map(({ cursor_created_at, ...order }) => order),
      next_cursor: hasMore ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    // SQLSTATE class 22: cursor decoded but holds a bad timestamp or id.
    if (after && typeof err.code === "string" && err.code.startsWith("22")) {
      return res.status(400).json({ error: "invalid cursor" });
    }
    next(err);
  }
});

module.exports = router;
