const timer = setTimeout(() => controller.abort(), 5000);
try {
  const res = await fetch(url, { signal: controller.signal });
} finally {
  clearTimeout(timer);
}
```

Here the rejection is an `AbortError`, and the timer stops once headers arrive.

```js
function throttle(fn, wait) {
  let last = 0;
  let timer = null;
  let lastArgs, lastThis;

  return function (...args) {
    lastArgs = args;
    lastThis = this;
    const remaining = wait - (Date.now() - last);

    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = Date.now();
      fn.apply(lastThis, lastArgs);
    } else if (!timer) {
      timer = setTimeout(() => {
        timer = null;
        last = Date.now();
        fn.apply(lastThis, lastArgs);
      }, remaining);
    }
  };
}

window.addEventListener("scroll", throttle(onScroll, 200), { passive: true });
```

The first event runs at once. Later events inside the 200 ms window collapse into one trailing call, so the handler still sees the final scroll position.
